insert into public.movies(title,description,"releaseYear","durationMinutes","directorID","genreID",rating,"posterUrl","watchUrl","watchSourceUrl","licenseUrl",attribution,"isFree",moods,"vibeTags",intensity,published,"languageName") select 'Любовь в СССР','Влюблённость студента становится началом непростого взросления. Молодым героям приходится выбирать между дружбой, чувствами и привычной жизнью.',2012,90,(select "directorID" from public.directors where "fullName"='Карен Шахназаров' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Romance' order by "genreID" limit 1),0,'/assets/posters/lyubov-v-sssr.jpg','https://www.mosfilm.ru/cinema/films/lyubov-v-sssr/','https://rutube.ru/play/embed/84936a4a7e583599f9499267745cd3d3/','https://www.mosfilm.ru/cinema/films/lyubov-v-sssr/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['romantic','emotional'],array['Полный фильм','Мосфильм','На русском'],3,true,'Русский' where not exists(select 1 from public.movies where title='Любовь в СССР' and "releaseYear"=2012);
