insert into public.movies(title,description,"releaseYear","durationMinutes","directorID","genreID",rating,"posterUrl","watchUrl","watchSourceUrl","licenseUrl",attribution,"isFree",moods,"vibeTags",intensity,published,"languageName") select 'Палата №6','Врач провинциальной больницы всё чаще беседует с пациентом психиатрического отделения. Встречи заставляют его пересмотреть собственные убеждения. Экранизация Чехова; режиссёры Карен Шахназаров и Александр Горновский.',2009,87,(select "directorID" from public.directors where "fullName"='Карен Шахназаров' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Drama' order by "genreID" limit 1),0,'/assets/posters/palata-6.jpg','https://www.mosfilm.ru/cinema/films/palata-6/','https://rutube.ru/play/embed/48be756b83375cacdb5a9b6bb81b0e89/','https://www.mosfilm.ru/cinema/films/palata-6/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['thoughtful'],array['Полный фильм','Мосфильм','На русском'],5,true,'Русский' where not exists(select 1 from public.movies where title='Палата №6' and "releaseYear"=2009);
