insert into public.movies(title,description,"releaseYear","durationMinutes","directorID","genreID",rating,"posterUrl","watchUrl","watchSourceUrl","licenseUrl",attribution,"isFree",moods,"vibeTags",intensity,published,"languageName") select 'Белый Тигр','После тяжёлого ранения танкист теряет память, но обретает необычную способность чувствовать боевые машины. Он стремится найти и уничтожить загадочный немецкий танк «Белый тигр».',2012,109,(select "directorID" from public.directors where "fullName"='Карен Шахназаров' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='War' order by "genreID" limit 1),0,'/assets/posters/belyy-tigr.jpg','https://www.mosfilm.ru/cinema/films/belyy-tigr/','https://www.youtube.com/embed/G-z1-uHyaus','https://www.mosfilm.ru/cinema/films/belyy-tigr/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['adrenaline','thoughtful'],array['Полный фильм','Мосфильм','На русском'],5,true,'Русский' where not exists(select 1 from public.movies where title='Белый Тигр' and "releaseYear"=2012);
