-- Keep the public catalog limited to complete films with covers.
begin;
update public.movies set "posterUrl"='https://video.blender.org/lazy-static/thumbnails/' || substring("watchSourceUrl" from '/videos/embed/([a-f0-9-]{36})$') || '.jpg' where "isFree" and "posterUrl"='' and "watchSourceUrl" ~ '^https://video\.blender\.org/videos/embed/[a-f0-9-]{36}$';
update public.movies set published=false where published and not ("isFree" and "posterUrl"<>'' and "watchSourceUrl" ~ '^https://(video\.blender\.org/videos/embed/[a-f0-9-]{36}|rutube\.ru/play/embed/[a-f0-9]{32}/|www\.youtube(-nocookie)?\.com/embed/[A-Za-z0-9_-]{11}|download\.blender\.org/[^?#]+\.mp4)$');
alter table public.movies drop constraint if exists movies_published_full_movie;
alter table public.movies add constraint movies_published_full_movie check(not published or ("isFree" and "posterUrl"<>'' and "watchSourceUrl" ~ '^https://(video\.blender\.org/videos/embed/[a-f0-9-]{36}|rutube\.ru/play/embed/[a-f0-9]{32}/|www\.youtube(-nocookie)?\.com/embed/[A-Za-z0-9_-]{11}|download\.blender\.org/[^?#]+\.mp4)$'));
commit;
